/* Service worker. Generated by tools/build.mjs: the cache name and the shell list below are
 * stamped with the build id, so a new build is a new cache and the old one is deleted on
 * activate. There is no version constant to remember to bump, because a constant someone has
 * to remember is a constant that eventually goes stale.
 */
const CACHE = "pay-20b6693cb083";
const SHELL = [
  "./",
  "./app.css?v=20b6693cb083",
  "./app.js?v=20b6693cb083",
  "./qr-art.js?v=20b6693cb083",
  "./qrcode.js?v=20b6693cb083",
  "./duitnow-mark.js?v=20b6693cb083",
  "./data.js?v=20b6693cb083"
];

self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (e) => {
  e.waitUntil(
    caches.keys()
      .then((ks) => Promise.all(ks.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

/* Only ever cache a response that is ours, complete and not the result of a redirect. An
 * unguarded put is how a service worker ends up serving a sign-in page, an error page or a
 * captive-portal page as the app, permanently and invisibly, because the poisoned entry only
 * surfaces once the network is gone. */
function cacheable(r) {
  return r && r.status === 200 && r.type === "basic" && !r.redirected;
}

self.addEventListener("fetch", (e) => {
  const req = e.request;
  if (req.method !== "GET") return;

  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  /* /state.json IS NEVER TOUCHED BY THIS WORKER, in either direction.
   *
   * It says which codes are suspended, and it changes without a deploy, which is the whole
   * reason it exists. A cached copy is a suspended code still being shown, which is the single
   * failure the flag is there to prevent. Returning without calling respondWith lets the
   * request go straight to the network, so nothing here can hold a stale copy of it, and it
   * never enters the cache because it is never put there.
   *
   * Offline, the fetch simply fails and the app keeps the flag baked into the bundle. That is
   * the fail-safe, and it is why this file may ignore this URL rather than fall back for it. */
  if (url.pathname === "/state.json") return;

  // Navigations go to the network first so a deploy lands on the next open. Everything else
  // is stamped with the build id in its query string, so a cache hit is by definition the
  // right version and a new build simply misses.
  if (req.mode === "navigate") {
    e.respondWith(
      fetch(req)
        .then((r) => {
          if (cacheable(r)) {
            const copy = r.clone();
            caches.open(CACHE).then((c) => c.put(req, copy)).catch(() => {});
          }
          return r;
        })
        .catch(() => caches.match(req).then((r) => r || caches.match(SHELL[0])))
    );
    return;
  }

  e.respondWith(
    caches.match(req).then((hit) => {
      if (hit) return hit;
      return fetch(req).then((r) => {
        if (cacheable(r)) {
          const copy = r.clone();
          caches.open(CACHE).then((c) => c.put(req, copy)).catch(() => {});
        }
        return r;
      });
    })
  );
});
